package dev.eugheist.ttmodern;
final class AdvancedToolHudWorldClientAudit {
 static volatile boolean checked;static net.minecraft.world.item.ItemStack previous;static boolean shift;
 static void tick(net.minecraft.client.Minecraft mc,int tick){
  if(tick==840)mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());previous=p.getMainHandItem().copy();shift=p.isShiftKeyDown();p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new net.minecraft.world.item.ItemStack(AwakenedPick.ITEM.get()));p.setShiftKeyDown(true);});
  if(tick==850){EnchanterClientAudit.check(mc.player.getMainHandItem().is(AwakenedPick.ITEM.get()),"native pick held-item sync");mc.setScreen(null);mc.player.setShiftKeyDown(true);mc.player.input.shiftKeyDown=true;mc.gameMode.useItem(mc.player,net.minecraft.world.InteractionHand.MAIN_HAND);EnchanterClientAudit.check(AdvancedToolModes.get(mc.player.getMainHandItem())==1&&AdvancedToolHud.text.equals(AdvancedToolModes.description("pick",mc.player.getMainHandItem()).getString()),"native client shift-use predicts mode and original HUD text");}
  if(tick==865){EnchanterClientAudit.check(AdvancedToolModes.get(mc.player.getMainHandItem())==1&&AdvancedToolHud.remaining>370,"server confirms single mode change without duplicate increment");EnchanterClientAudit.Client.shot(mc,"awakened-pick-mode-hud.png");mc.player.input.shiftKeyDown=false;mc.player.setShiftKeyDown(false);mc.getSingleplayerServer().execute(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());try{EnchanterClientAudit.check(AdvancedToolModes.get(p.getMainHandItem())==1,"native use-item packet changed server mode once");checked=true;System.out.println("TT ADVANCED TOOL HUD WORLD CLIENT AUDIT: ALL PASS (native shift-use prediction/server packet/single mode update,localized HUD/native render,restored held item)");}finally{p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,previous);p.setShiftKeyDown(shift);}});}
 }
}
